+  async changeKeyExpire(keyId, daysFromNow) {
+    const key = lazy.EnigmailKeyRing.getKeyById(keyId);
+    let expirationTime = 0;
+    if (daysFromNow) {
+      const later = new Date();
+      later.setDate(later.getDate() + daysFromNow);
